def serve_stdio(
    output: Path,
    *,
    input_stream: TextIO | None = None,
    output_stream: TextIO | None = None,
    retrieve: Callable[..., dict[str, Any]] | None = None,
    record_explanation: Callable[[Path, dict[str, Any], dict[str, Any]], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Serve newline-delimited retrieval requests until shutdown or EOF.

    The transport is deliberately local and single-threaded.  Every response
    is one compact JSON line, so a Harness can keep this process alive for one
    task without opening a port or introducing a service dependency.
    """

    output = output.resolve()
    if not (output / "machine/knowledge.sqlite").is_file():
        raise CkbError("machine knowledge is missing; run finalize or machine-reindex")
    if input_stream is None and hasattr(sys.stdin, "reconfigure"):
        sys.stdin.reconfigure(encoding="utf-8", errors="strict", newline="\n")
    if output_stream is None and hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="strict", newline="\n", write_through=True)
    source = input_stream or sys.stdin
    destination = output_stream or sys.stdout
    retrieve_value = retrieve or retrieve_machine
    record_value = record_explanation or _record_explanation
    retrievals: dict[str, dict[str, Any]] = {}
    presented_scope_offers: set[str] = set()
    handled = 0
    succeeded = 0
    failed = 0
    shutdown = False
    for raw_line in source:
        line = raw_line.strip()
        if not line:
            continue
        handled += 1
        request_id: Any = None
        method: Any = None
        started = time.perf_counter_ns()
        try:
            request = json.loads(line)
            if not isinstance(request, dict):
                raise CkbError("stdio request must be a JSON object")
            request_id = request.get("id")
            if not isinstance(request_id, (str, int)) or isinstance(request_id, bool):
                raise CkbError("stdio request id must be a string or integer")
            method = request.get("method")
            if method == "ping":
                result = {
                    "status": "ready",
                    "protocol": STDIO_RETRIEVAL_PROTOCOL,
                    "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
                    "output": str(output),
                    "methods": [
                        "ping",
                        "retrieve",
                        "brief",
                        "entity",
                        "neighbors",
                        "source",
                        "changes",
                        "record-explanation",
                        "shutdown",
                    ],
                }
            elif method in {"retrieve", "brief"}:
                question = request.get("question")
                if not isinstance(question, str) or not question.strip():
                    raise CkbError("stdio retrieve question must be a non-empty string")
                question = _utf8_safe(question).strip()
                budget = _integer(request.get("budget", 1500), "budget", 200, 1_000_000)
                max_pages = _integer(request.get("max_pages", 8), "max_pages", 1, 32)
                profile = request.get("profile", "fast")
                if profile not in {"fast", "precise"}:
                    raise CkbError("stdio retrieve profile must be fast or precise")
                keyword_fallback = _keyword_fallback_options(request)
                if keyword_fallback is None:
                    result = retrieve_value(output, question, budget, max_pages, profile)
                else:
                    result = retrieve_value(
                        output,
                        question,
                        budget,
                        max_pages,
                        profile,
                        keyword_fallback=keyword_fallback,
                    )
                status = result.get("status")
                offer = result.get("scope_extension_offer") or {}
                offer_id = offer.get("offer_id")
                if isinstance(offer_id, str) and offer_id in presented_scope_offers:
                    result = dict(result)
                    result.pop("scope_extension_offer", None)
                    result["scope_extension_diagnostic"] = {
                        "schema_version": 1,
                        "status": "not-offered",
                        "code": "offer-already-presented",
                        "message_zh": "同一 stdio 会话已返回过该扩库确认，本次保留窄读结果且不重复询问。",
                        "candidates": [str((offer.get("selector") or {}).get("value") or "")],
                    }
                elif isinstance(offer_id, str):
                    presented_scope_offers.add(offer_id)
                if status == "passed":
                    if not result.get("pack"):
                        raise CkbError("stdio retrieve did not return a passed Agent pack")
                    retrievals[str(request_id)] = {**result, "request_id": str(request_id)}
                elif status == "needs-source-read":
                    pass
                else:
                    raise CkbError("stdio retrieve returned an unsupported status")
                if method == "brief":
                    result = compact_agent_brief(output, result)
            elif method == "entity":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio entity selector must be a non-empty string")
                result = entity_lookup(output, _utf8_safe(selector).strip())
            elif method == "neighbors":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio neighbors selector must be a non-empty string")
                depth = _integer(request.get("depth", 1), "depth", 1, 8)
                limit = _integer(request.get("limit", 50), "limit", 1, 500)
                relation = request.get("relation")
                if relation is not None and not isinstance(relation, str):
                    raise CkbError("stdio neighbors relation must be a string")
                result = neighbor_lookup(output, _utf8_safe(selector).strip(), depth, relation, limit)
            elif method == "source":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio source selector must be a non-empty string")
                context_lines = _integer(request.get("context_lines", 3), "context_lines", 0, 100)
                result = source_lookup(output, _utf8_safe(selector).strip(), context_lines)
            elif method == "changes":
                kind = request.get("kind")
                if kind is not None and not isinstance(kind, str):
                    raise CkbError("stdio changes kind must be a string")
                limit = _integer(request.get("limit", 20), "limit", 1, 500)
                result = change_documents(output, kind, limit)
            elif method == "record-explanation":
                retrieval_id = request.get("retrieval_request_id")
                if not isinstance(retrieval_id, (str, int)) or isinstance(retrieval_id, bool):
                    raise CkbError("stdio record-explanation retrieval_request_id must be a string or integer")
                retrieval = retrievals.get(str(retrieval_id))
                if retrieval is None:
                    raise CkbError("stdio record-explanation requires a completed retrieval from this server session")
                result = record_value(output, request, retrieval)
            elif method == "shutdown":
                result = {"status": "shutting-down"}
                shutdown = True
            else:
                raise CkbError(
                    "stdio request method must be ping, retrieve, brief, entity, neighbors, source, "
                    "changes, record-explanation, or shutdown"
                )
            succeeded += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": True,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "result": result,
                },
            )
        except (json.JSONDecodeError, CkbError) as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": exc.exit_code if isinstance(exc, CkbError) else 2,
                    },
                },
            )
        except Exception as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": 1,
                    },
                },
            )
        if shutdown:
            break
    return {
        "schema_version": 1,
        "status": "stopped",
        "protocol": STDIO_RETRIEVAL_PROTOCOL,
        "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
        "requests": handled,
        "succeeded": succeeded,
        "failed": failed,
        "shutdown_requested": shutdown,
    }

"""Human-first navigation for durable Agent work records.

The index treats every analysis, change, pitfall, experiment, and session note
uniformly.  It never receives task-specific keywords or a hand-picked result
set; titles and one-line descriptions come from the existing reviewed notes.
"""

from __future__ import annotations

from pathlib import Path
import re
from typing import Any

from .common import CkbError, json_write
from .obsidian import NOTE_DIRECTORIES


WORK_RECORD_INDEX = "RECORDS.md"
WORK_RECORD_TAG = "#类型/导览"
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")
CHINESE_RE = re.compile(r"[\u3400-\u9fff]")
SECTIONS = {
    "analysis": ("分析与方案", "查找已经形成的结论、方案比较、边界和后续判断。"),
    "changes": ("实现与修改", "查找已经修改的内容、修改原因、验证结果和交付范围。"),
    "experiments": ("实验与性能", "查找测试协议、性能数字、对照结果和适用限制。"),
    "pitfalls": ("问题与限制", "查找失败原因、环境差异、规避条件和复现入口。"),
    "sessions": ("会话与方案变化", "查找一次任务的目标、执行范围、结果和待继续事项。"),
}
SECTION_ORDER = ("analysis", "changes", "experiments", "pitfalls", "sessions")


def _contains_chinese(value: str) -> bool:
    return len(CHINESE_RE.findall(value)) >= 2


def _title(text: str, fallback: str) -> str:
    first = text.splitlines()[0] if text else ""
    return first.removeprefix("# ").strip() or fallback


def _plain_text(value: str) -> str:
    value = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", value)
    value = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", value)
    value = re.sub(r"\[\[([^\]|#]+)(?:[|#][^\]]*)?\]\]", r"\1", value)
    value = re.sub(r"[`*>#]", "", value)
    return re.sub(r"\s+", " ", value).strip()


def _first_narrative(text: str) -> str:
    if "\n## 后续补充\n" in text:
        text = text.rsplit("\n## 后续补充\n", 1)[1]
    paragraphs: list[str] = []
    current: list[str] = []
    fenced = False
    for raw in text.splitlines()[1:]:
        line = raw.strip()
        if line.startswith("```"):
            fenced = not fenced
            continue
        if fenced:
            continue
        if not line:
            if current:
                paragraphs.append(" ".join(current))
                current = []
            continue
        if line.startswith(("#", "标签：", "- [[", "- [打开源码：", "|", "<!--")):
            continue
        if re.match(r"^[-*+]\s+", line) or re.match(r"^\d+[.)]\s+", line):
            continue
        current.append(line)
    if current:
        paragraphs.append(" ".join(current))
    for paragraph in paragraphs:
        value = _plain_text(paragraph)
        if not _contains_chinese(value):
            continue
        sentence = re.match(r"^(.{12,140}?[。！？；])(?:\s|$)", value)
        if sentence:
            return sentence.group(1)
        if len(value) <= 120:
            return value
        return value[:117].rstrip("，、；： ") + "……"
    return "本记录保存一次经过审阅的任务结论、实现变化或验证结果。"


def collect_work_records(root: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen_titles: set[str] = set()
    for directory in SECTION_ORDER:
        for path in sorted((root / directory).glob("*.md"), key=lambda item: item.name.casefold()):
            text = path.read_text(encoding="utf-8-sig")
            title = _title(text, path.stem)
            if title == "工作记录导览":
                raise CkbError("work record title conflicts with generated navigation: 工作记录导览")
            if title in seen_titles:
                raise CkbError(f"work record title must be unique: {title}")
            seen_titles.add(title)
            records.append(
                {
                    "title": title,
                    "directory": directory,
                    "file": path.relative_to(root).as_posix(),
                    "summary": _first_narrative(text),
                }
            )
    return records


def render_work_record_index(root: Path) -> tuple[str, list[dict[str, Any]]]:
    records = collect_work_records(root)
    lines = [
        "# 工作记录导览",
        "",
        f"标签：{WORK_RECORD_TAG}",
        "",
        "> 按任务选择已有结论、实现变化和实验结果；先读摘要，再核对记录的时间与适用范围。",
        "",
        "## 先选择你要查找的内容",
        "",
        "- 需要理解已有结论或设计边界时，查看“分析与方案”。",
        "- 需要确认已经修改什么以及如何验证时，查看“实现与修改”。",
        "- 需要比较性能、召回、上下文或其他量化结果时，查看“实验与性能”。",
        "- 需要避开已知失败和环境差异时，查看“问题与限制”。",
        "- 需要恢复一次任务的上下文时，查看“会话与方案变化”。",
        "",
        "## 让 Agent 帮助查找",
        "",
        "在 Obsidian 中先使用本页标题浏览；记录较多时，再用核心搜索输入任务中的两个或三个稳定关键词。需要定位源码时，转到首页的确定性检索入口。",
        "",
    ]
    from .research_gaps import gap_navigation_counts

    gap_counts = gap_navigation_counts(root)
    if gap_counts is not None:
        lines.extend(
            [
                "## 研究缺口与待补来源",
                "",
                "尚缺来源的主张保留为待验证事项。请让 Agent 查找与你的问题有关的研究缺口及现有证据，不将未决事项当作已确认事实。",
                "",
                f"- 当前共 {gap_counts['total']} 项：待补证据 {gap_counts['open']} 项，暂缓 {gap_counts['deferred']} 项，已关闭 {gap_counts['resolved']} 项。",
                "",
            ]
        )
    by_directory = {directory: [] for directory in NOTE_DIRECTORIES}
    for record in records:
        by_directory[record["directory"]].append(record)
    for directory in SECTION_ORDER:
        heading, description = SECTIONS[directory]
        lines.extend([f"## {heading}", "", description, ""])
        items = by_directory[directory]
        if items:
            lines.extend(f"- [[{item['title']}]] — {item['summary']}" for item in items)
        else:
            lines.append("- 当前没有这一类记录。")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n", records


def write_work_record_index(root: Path) -> dict[str, Any]:
    text, records = render_work_record_index(root)
    target = root / WORK_RECORD_INDEX
    target.write_text(text, encoding="utf-8", newline="\n")
    return {
        "status": "ready",
        "file": str(target.resolve()),
        "record_count": len(records),
        "sections": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
    }


def refresh_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    if not markdown.is_dir() or not human.is_dir():
        raise CkbError("work record navigation requires human and markdown roots")
    text, records = render_work_record_index(markdown)
    for root in (markdown, human):
        (root / WORK_RECORD_INDEX).write_text(text, encoding="utf-8", newline="\n")
    audit = audit_work_record_index(output)
    json_write(output / "workspace-meta/work-record-index-audit.json", audit)
    if audit["status"] != "passed":
        raise CkbError(f"work record navigation audit failed: {audit['errors'][:10]}")
    return {"status": "passed", "record_count": len(records), "audit": audit}


def audit_work_record_root(root: Path) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    target = root / WORK_RECORD_INDEX
    try:
        expected, records = render_work_record_index(root)
    except CkbError as exc:
        return {"status": "failed", "record_count": 0, "errors": [{"reason": "work-record-collection", "detail": str(exc)}]}
    if not target.is_file():
        errors.append({"reason": "work-record-index-missing"})
        actual = ""
    else:
        actual = target.read_text(encoding="utf-8-sig")
        if actual != expected:
            errors.append({"reason": "work-record-index-stale"})
        if actual.startswith("---\n"):
            errors.append({"reason": "work-record-index-frontmatter"})
        if actual.count(WORK_RECORD_TAG) != 1:
            errors.append({"reason": "work-record-index-tag", "count": actual.count(WORK_RECORD_TAG)})
        if LONG_HEX.search(actual):
            errors.append({"reason": "work-record-index-hash"})
    expected_titles = {item["title"] for item in records}
    linked_titles = set(re.findall(r"\[\[([^\]|#]+)", actual))
    if linked_titles != expected_titles:
        errors.append(
            {
                "reason": "work-record-index-link-set",
                "missing": sorted(expected_titles - linked_titles),
                "extra": sorted(linked_titles - expected_titles),
            }
        )
    missing_summaries = [item["title"] for item in records if not _contains_chinese(item["summary"])]
    if missing_summaries:
        errors.append({"reason": "work-record-index-summary-not-chinese", "titles": missing_summaries})
    return {
        "status": "passed" if not errors else "failed",
        "record_count": len(records),
        "linked_record_count": len(linked_titles & expected_titles),
        "section_counts": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
        "errors": errors,
    }


def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

"""Mutable human notes and working-tree session records layered over a baseline KB."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
from typing import Any

from .common import CkbError, json_load, json_write, run, safe_title, stable_id, utc_now
from .obsidian import NOTE_DIRECTORIES
from .source_links import ensure_local_openers, obsidian_open_uri, source_markdown_link
from .machine_knowledge import contains_chinese_narrative
from .work_record_index import refresh_work_record_index


TAG_BY_KIND = {
    "analysis": "#类型/分析",
    "change": "#类型/变更",
    "pitfall": "#类型/踩坑",
    "experiment": "#类型/实验",
    "session": "#类型/会话",
}
DIRECTORY_BY_KIND = dict(zip(TAG_BY_KIND, NOTE_DIRECTORIES))
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")


def page_tag(page_type: str) -> str:
    if page_type == "boundary":
        return "#类型/边界"
    if page_type in {"repository", "module"}:
        return "#类型/职责"
    return "#类型/代码"


def _markdown_root(output: Path) -> Path:
    root = output / "markdown"
    if not (root / "projection.json").is_file():
        raise CkbError(f"Markdown projection is required before recording knowledge notes: {root}")
    return root


def _resolve_page_titles(output: Path, selectors: list[str], query_record: Path | None) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    pages = projection.get("pages", [])
    title_by_id = {page["id"]: page["title"] for page in pages}
    titles = set(title_by_id.values())
    folded = {title.casefold(): title for title in titles}
    selected: list[str] = []
    for selector in selectors:
        exact = folded.get(selector.casefold())
        if exact:
            selected.append(exact)
            continue
        partial = sorted(title for title in titles if selector.casefold() in title.casefold())
        if len(partial) != 1:
            raise CkbError(f"knowledge-page selector must match one page: {selector}; candidates={partial[:20]}")
        selected.append(partial[0])
    if query_record:
        query = json_load(query_record)
        for page in query.get("selected_pages", []):
            title = page.get("title")
            if title in titles:
                selected.append(title)
        owners = projection.get("entity_owner_pages", {})
        for node in query.get("nodes", []):
            node_id = node.get("id")
            page_id = owners.get(node_id) or (node_id if node_id in title_by_id else None)
            if page_id in title_by_id:
                selected.append(title_by_id[page_id])
        for entity in query.get("selected_entities", []):
            title = entity.get("human_page_title")
            if title in titles:
                selected.append(title)
    return list(dict.fromkeys(selected))


def _source_links_for_titles(output: Path, titles: list[str]) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    page_by_title = {page["title"]: page for page in projection.get("pages", [])}
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    links = []
    for title in titles:
        page = page_by_title.get(title)
        entity = entity_by_id.get(page.get("id")) if page else None
        if not entity or not entity.get("path") or not entity.get("range"):
            continue
        links.append(
            source_markdown_link(
                openers,
                entity["path"],
                int(entity["range"]["start_line"]),
                int(entity["range"]["end_line"]),
            )
        )
    return links


def read_note_body(body_path: Path) -> str:
    """Read and validate one user-authored knowledge-note body."""

    if not body_path.is_file():
        raise CkbError(f"note body does not exist: {body_path}")
    try:
        body = body_path.read_text(encoding="utf-8-sig").strip()
    except UnicodeDecodeError as exc:
        raise CkbError(f"note body must be valid UTF-8: {exc}") from exc
    if not body:
        raise CkbError("note body must not be empty")
    if not contains_chinese_narrative(body):
        raise CkbError("knowledge note descriptions must use Simplified Chinese; English proper nouns and code identifiers are allowed")
    if body.startswith("---\n") or LONG_HEX.search(body):
        raise CkbError("human knowledge notes must omit frontmatter and hash-like identifiers")
    from .human_page_templates import human_output_errors

    errors = human_output_errors(body)
    if errors:
        raise CkbError(f"human output contract failed before note write: {errors[:10]}")
    return body


def render_note_text(kind: str, title: str, body: str, linked_titles: list[str], source_links: list[str], *, v3: bool = False) -> str:
    # A typed authoring package already has a complete title and V3 sections.
    # Links not selected by its author remain metadata, never extra sections.
    if v3:
        first, _, remainder = body.partition("\n")
        if first != f"# {title.strip()}":
            raise CkbError("authoring title must match the record title")
        return f"{first}\n\n标签：{TAG_BY_KIND[kind]}\n\n{remainder.strip()}\n"
    sections = [f"# {title.strip()}", "", f"标签：{TAG_BY_KIND[kind]}", "", body]
    if linked_titles:
        sections.extend(["", "## 相关知识页", "", *[f"- [[{value}]]" for value in linked_titles]])
    if source_links:
        sections.extend(["", "## 源码入口", "", *[f"- {value}" for value in source_links]])
    text = "\n".join(sections).rstrip() + "\n"
    if LONG_HEX.search(text):
        raise CkbError("generated human knowledge note contains a hash-like identifier")
    return text


def note_contract_metadata(body_path: Path, kind: str, body: str) -> dict[str, Any]:
    """Recheck an explicit V3 package; never label a legacy body as V3 reviewed."""
    from .human_page_templates import validate_human_page, human_page_template_registry_sha256

    manifest_path = body_path.parent / "manifest.json"
    if not manifest_path.is_file():
        return {"human_output_contract": {"status": "legacy-content-checked", "v3_validated": False}}
    manifest = json_load(manifest_path)
    if not isinstance(manifest, dict) or not {"page_type", "contract_version"}.issubset(manifest):
        return {"human_output_contract": {"status": "legacy-content-checked", "v3_validated": False}}
    if not {"body", "section_evidence", "section_evidence_sha256"}.issubset(manifest):
        raise CkbError("record authoring manifest is missing its body or section evidence")
    if manifest.get("page_type") != kind or manifest.get("contract_version") != "3.0.0":
        raise CkbError("record authoring package type or contract version differs")
    if manifest.get("registry_sha256") != human_page_template_registry_sha256():
        raise CkbError("record authoring package registry is stale; validate and package again")
    if manifest.get("body", {}).get("sha256") != hashlib.sha256(body_path.read_bytes()).hexdigest():
        raise CkbError("record authoring body differs from its manifest")
    context = manifest.get("validation_context")
    if not isinstance(context, dict):
        raise CkbError("record authoring package needs replayable V3 validation context")
    validation = validate_human_page(kind, body, context=context)
    if validation["status"] != "passed":
        raise CkbError(f"record V3 contract failed: {validation['errors'][:10]}")
    evidence = manifest.get("section_evidence", {})
    digest = hashlib.sha256((json.dumps(evidence, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()).hexdigest()
    if digest != manifest.get("section_evidence_sha256"):
        raise CkbError("record section evidence differs from its manifest")
    for section in evidence.get("sections", []):
        for field in ("source_refs", "machine_evidence_refs"):
            for ref in section.get(field, []):
                if ref.get("target_basis") == "uri":
                    continue
                target = (manifest_path.parent / ref["target"]).resolve()
                if manifest_path.parent.resolve() not in target.parents:
                    raise CkbError("record package evidence escapes its package")
                if not target.is_file() or hashlib.sha256(target.read_bytes()).hexdigest() != ref.get("sha256"):
                    raise CkbError("record package evidence is missing or drifted")
    return {
        "human_output_contract": {"status": "v3-validated", "v3_validated": True},
        "section_evidence": evidence,
        "section_evidence_sha256": digest,
        "validation_context": context,
        "authoring_package": str(manifest_path.resolve()),
    }


def record_note(
    output: Path,
    kind: str,
    title: str,
    body_path: Path,
    selectors: list[str] | None = None,
    query_record: Path | None = None,
    append: bool = False,
    reindex: bool = True,
) -> dict[str, Any]:
    if kind not in TAG_BY_KIND:
        raise CkbError(f"note kind must be one of: {sorted(TAG_BY_KIND)}")
    body = read_note_body(body_path)
    contract_metadata = note_contract_metadata(body_path, kind, body)
    root = _markdown_root(output)
    linked_titles = _resolve_page_titles(output, selectors or [], query_record)
    if kind != "session" and not linked_titles:
        raise CkbError(f"{kind} notes require at least one linked knowledge page")
    source_links = _source_links_for_titles(output, linked_titles)
    filename = safe_title(title) + ".md"
    directory = root / DIRECTORY_BY_KIND[kind]
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / filename
    if target.exists() and not append:
        raise CkbError(f"knowledge note already exists: {target}; use --append to add a revision")
    text = render_note_text(kind, title, body, linked_titles, source_links, v3=contract_metadata["human_output_contract"]["v3_validated"])
    previous_record = None
    previous_record_path = output / "workspace-meta" / "notes" / (safe_title(title) + ".json")
    if append and previous_record_path.is_file():
        previous_record = json_load(previous_record_path)
    if append and (contract_metadata["human_output_contract"]["v3_validated"] or (previous_record or {}).get("section_evidence")):
        raise CkbError("V3 sections require a complete validated replacement; append is reserved for legacy notes")
    if append and target.exists():
        existing = target.read_text(encoding="utf-8")
        text = existing.rstrip() + "\n\n## 后续补充\n\n" + body + "\n"
    target.write_text(text, encoding="utf-8", newline="\n")
    from .knowledge_layers import mirror_note

    relative_note = Path(DIRECTORY_BY_KIND[kind]) / filename
    mirror_note(output, relative_note)
    human_target = output / "human" / relative_note
    meta_dir = output / "workspace-meta" / "notes"
    meta_dir.mkdir(parents=True, exist_ok=True)
    now = utc_now()
    record = {
        "schema_version": 1,
        "status": "agent-reviewed",
        "record_id": (previous_record or {}).get("record_id")
        or stable_id("work-record", kind, title.strip().casefold(), relative_note.as_posix()),
        "kind": kind,
        "title": title.strip(),
        "file": str((human_target if human_target.is_file() else target).resolve()),
        "compatibility_file": str(target.resolve()),
        "linked_pages": linked_titles,
        "source_links": source_links,
        "query_record": str(query_record.resolve()) if query_record else None,
        "created_at_utc": (previous_record or {}).get("created_at_utc") or (previous_record or {}).get("updated_at_utc") or now,
        "updated_at_utc": now,
        "body_sha256": hashlib.sha256((body.rstrip() + "\n").encode("utf-8")).hexdigest(),
        "obsidian_uri": obsidian_open_uri(target),
        **contract_metadata,
    }
    json_write(meta_dir / (safe_title(title) + ".json"), record)
    refresh_work_record_index(output)
    errors = audit_notes(output)
    if errors:
        raise CkbError(f"knowledge-note audit failed: {errors[:10]}")
    if reindex and (output / "agent-index.sqlite").is_file():
        from .agent_index import build_agent_index

        build_agent_index(output)
    if reindex and (output / "machine/knowledge.sqlite").is_file():
        from .machine_knowledge import build_machine_knowledge, sync_workspace_changes

        build_machine_knowledge(output)
        sync_workspace_changes(output)
    return record


def queue_pending_note(
    output: Path,
    kind: str,
    title: str,
    body: str,
    *,
    query_record: Path | None = None,
    changed_paths: list[str] | None = None,
) -> dict[str, Any]:
    """Queue a Chinese Agent note while the human projection is still building."""
    if kind not in TAG_BY_KIND:
        raise CkbError(f"note kind must be one of: {sorted(TAG_BY_KIND)}")
    if not contains_chinese_narrative(body):
        raise CkbError("pending knowledge note descriptions must use Simplified Chinese; English proper nouns and code identifiers are allowed")
    directory = output / "workspace-meta/pending-notes"
    directory.mkdir(parents=True, exist_ok=True)
    stem = safe_title(title)
    counter = 1
    while (directory / f"{stem}-{counter:02d}.json").exists():
        counter += 1
    record_path = directory / f"{stem}-{counter:02d}.json"
    body_path = record_path.with_suffix(".md")
    body_path.write_text(body.strip() + "\n", encoding="utf-8", newline="\n")
    record = {
        "schema_version": 1,
        "status": "pending-human-projection",
        "kind": kind,
        "title": title,
        "body": str(body_path.resolve()),
        "query_record": str(query_record.resolve()) if query_record else None,
        "changed_paths": sorted(set(changed_paths or [])),
        "queued_at_utc": utc_now(),
    }
    json_write(record_path, record)
    return {**record, "record": str(record_path.resolve())}


def selectors_for_changed_paths(output: Path, changed_paths: list[str]) -> list[str]:
    """Map working-tree paths to deterministic owner pages, with repository fallback."""
    selected_paths = {value.replace("\\", "/") for value in changed_paths}
    if not selected_paths:
        return []
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    title_by_id = {page["id"]: page["title"] for page in projection.get("pages", [])}
    owners = projection.get("entity_owner_pages", {})
    selectors: list[str] = []
    for entity in graph.get("entities", []):
        if str(entity.get("path", "")).replace("\\", "/") in selected_paths:
            owner = owners.get(entity["id"]) or (entity["id"] if entity["id"] in title_by_id else None)
            if owner in title_by_id:
                selectors.append(title_by_id[owner])
    selectors = list(dict.fromkeys(selectors))
    if selectors:
        return selectors
    repository_pages = [
        page["title"]
        for page in projection.get("pages", [])
        if page.get("page_type") == "repository"
    ]
    return repository_pages[:1]


def materialize_pending_notes(output: Path) -> list[dict[str, Any]]:
    directory = output / "workspace-meta/pending-notes"
    if not directory.is_dir():
        return []
    results: list[dict[str, Any]] = []
    for path in sorted(directory.glob("*.json")):
        pending = json_load(path)
        if pending.get("status") == "materialized":
            continue
        selectors = selectors_for_changed_paths(output, list(pending.get("changed_paths", [])))
        query_record = Path(pending["query_record"]) if pending.get("query_record") else None
        if query_record and not query_record.is_file():
            query_record = None
        result = record_note(
            output,
            str(pending["kind"]),
            str(pending["title"]),
            Path(pending["body"]),
            selectors=selectors,
            query_record=query_record,
            append=False,
            reindex=False,
        )
        pending["status"] = "materialized"
        pending["materialized_file"] = result["file"]
        pending["materialized_at_utc"] = utc_now()
        json_write(path, pending)
        results.append(result)
    return results


def audit_notes(output: Path) -> list[dict[str, Any]]:
    root = output / "markdown"
    if not root.is_dir():
        return [{"reason": "markdown-vault-missing"}]
    projection = json_load(root / "projection.json")
    titles = {page["title"] for page in projection.get("pages", [])}
    notes = []
    errors: list[dict[str, Any]] = []
    for kind, directory_name in DIRECTORY_BY_KIND.items():
        directory = root / directory_name
        if not directory.is_dir():
            errors.append({"reason": "note-directory-missing", "directory": directory_name})
            continue
        for path in sorted(directory.glob("*.md")):
            text = path.read_text(encoding="utf-8")
            note_title = text.splitlines()[0].removeprefix("# ").strip() if text else ""
            notes.append(note_title)
            expected_tag = TAG_BY_KIND[kind]
            tags = re.findall(r"#类型/[\w\u3400-\u9fff-]+", text)
            if tags != [expected_tag]:
                errors.append({"reason": "note-tag-invalid", "path": str(path), "tags": tags, "expected": expected_tag})
            if text.startswith("---\n"):
                errors.append({"reason": "note-frontmatter-visible", "path": str(path)})
            if LONG_HEX.search(text):
                errors.append({"reason": "note-hash-visible", "path": str(path)})
            narrative = "\n".join(
                line
                for line in text.splitlines()
                if not line.startswith(("#", "标签：", "- [[", "- [打开源码："))
            )
            if not contains_chinese_narrative(narrative):
                errors.append({"reason": "note-description-not-chinese", "path": str(path)})
    all_titles = titles | set(notes)
    for directory_name in NOTE_DIRECTORIES:
        for path in (root / directory_name).glob("*.md"):
            text = path.read_text(encoding="utf-8")
            for target in re.findall(r"\[\[([^\]|#]+)", text):
                if target not in all_titles:
                    errors.append({"reason": "note-link-dangling", "path": str(path), "target": target})
    return errors


def sync_workspace(output: Path, repo: Path) -> dict[str, Any]:
    state = json_load(output / "state.json")
    expected = Path(state["repository"]["root"]).resolve()
    actual = repo.resolve()
    if actual != expected:
        raise CkbError(f"workspace repository differs from the initialized repository: {actual}")
    status = run(["git", "-C", str(actual), "status", "--porcelain=v1", "--untracked-files=all"], timeout=60)
    if status.returncode:
        raise CkbError(f"git status failed: {status.stderr or status.stdout}")
    head = run(["git", "-C", str(actual), "rev-parse", "HEAD"], timeout=30)
    diff = run(["git", "-C", str(actual), "diff", "--no-color", "--no-ext-diff"], timeout=120)
    lines = [line for line in diff.stdout.splitlines() if not line.startswith("index ")]
    meta = output / "workspace-meta"
    meta.mkdir(parents=True, exist_ok=True)
    (meta / "working.patch").write_text("\n".join(lines).rstrip() + ("\n" if lines else ""), encoding="utf-8", newline="\n")
    changed = []
    untracked = []
    for line in status.stdout.splitlines():
        value = line[3:].strip().replace("\\", "/")
        (untracked if line.startswith("??") else changed).append(value)
    record = {
        "schema_version": 1,
        "status": "dirty" if status.stdout.strip() else "clean",
        "base_commit": state["repository"]["commit"],
        "working_head": head.stdout.strip(),
        "changed_paths": sorted(set(changed)),
        "untracked_paths": sorted(set(untracked)),
        "patch": str((meta / "working.patch").resolve()),
        "captured_at_utc": utc_now(),
    }
    json_write(meta / "working-overlay.json", record)
    if (output / "agent-index.sqlite").is_file() and (output / "markdown/projection.json").is_file():
        from .agent_index import build_agent_index

        build_agent_index(output)
    return record


def workspace_status(output: Path) -> dict[str, Any]:
    state = json_load(output / "state.json")
    overlay = output / "workspace-meta/working-overlay.json"
    return {
        "schema_version": 1,
        "status": "ready",
        "baseline": {
            "status": (state.get("source_snapshot") or {}).get("status", "legacy-live-worktree"),
            "commit": state["repository"]["commit"],
            "snapshot_root": (state.get("source_snapshot") or {}).get("root"),
        },
        "working_overlay": json_load(overlay) if overlay.is_file() else {"status": "not-synced"},
        "notes": {"status": "passed" if not audit_notes(output) else "failed"} if (output / "markdown/projection.json").is_file() else {"status": "waiting-for-markdown"},
    }
